def check(call, text, on, failed):
    broken = []
    if call["tool"] not in on:
        broken.append("tool")
    words = []
    for v in call["args"].values():
        words += str(v).split()
    if any(w not in text for w in words):
        broken.append("said")
    if failed:
        broken.append("after")
    return broken

