def score(cases):
    hits, total = {}, {}
    for g, want, got in cases:
        total[g] = total.get(g, 0) + 1
        if got == want:
            hits[g] = hits.get(g, 0) + 1
    out = {}
    for g in total:
        out[g] = hits.get(g, 0) / total[g]
    return out

